"""Client for the internal price service."""

import json
import os
import urllib.request
from urllib.parse import quote


BASE = "http://prices.internal/api/v1/price"


def get_price(sku: str) -> float:
    """Fetch the current price for *sku* from the internal service."""
    headers = {}
    token = os.environ.get("DEPLOY_TOKEN")
    if token:
        headers["Authorization"] = f"Bearer {token}"

    request = urllib.request.Request(
        f"{BASE}/{quote(str(sku), safe='')}", headers=headers
    )
    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list) -> float:
    """Return the sum of the live prices for the supplied SKUs."""
    return sum((get_price(sku) for sku in skus), 0)
PY
cd /work && pytest -q"}
